//! 🧪️ Actual prepared edit/root/seal custody includes every original allocator extent.
use std::sync::Arc;
use semio_framework_value::{ArtifactOwnedValueRetirementFactory, SnapshotRetirementFactory};
use semio_os_store_one_item_publication::{ArtifactStoreOneItemLiveAuthority, ArtifactStoreOneItemPrepared};
use semio_os_spr::{Edit, HybridLogicalTimestamp};
use semio_framework_value::retained_clone::{OriginalEffectReply,OriginalEffectReplyComplete,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
use semio_framework_value::{ErasedSnapshotRetirement,FactoryTicketClose,OriginalRetirementFailure,RetainedAllocationEffect,RetainedWorkOutcome,ValueError};
use semio_framework_value_clone_source_testing::drive::drive_reply;
use semio_framework_value_factory::{OwnedValueRetirementFactory,SharedValueRetirementFactory};
const STALL_TURNS:usize=64;
const UNITS:u64=64;
fn progress_of(answer:&Result<RetainedCloneStep,OriginalRetirementFailure>)->RetainedCloneProgress{match answer{Ok(step)=>step.progress(),Err(failure)=>failure.retained_progress()}}
fn close(owner:&mut Option<Box<dyn ErasedSnapshotRetirement>>,ticket:&mut FactoryTicketClose,body:usize,grant:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalRetirementFailure>{
 drive_reply(grant,UNITS,progress_of,|effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'_,RetainedCloneStep,OriginalRetirementFailure>,recover|->Result<OriginalEffectReplyComplete<'_,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{if recover{ticket.recover_close_into(owner,body,effect,reply)}else{ticket.close_into(owner,body,effect,reply)}})
}
#[test]
fn prepared_candidate_original_owners_retire_with_actual_allocator_receipts(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for body in law["copyGrants"].as_array().unwrap(){let body=body.as_u64().unwrap()as usize;
 let((prepared,mutations,snapshots),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let authority=Arc::new(ArtifactStoreOneItemLiveAuthority::mint(semio_framework_job::OperationId(11), semio_framework_job::Generation(7), [9;32], 3, 4, HybridLogicalTimestamp{actor:1,physical_ms:42,logical:2}, law["identities"][0].as_str().unwrap().into(), None, None, Some(law["identities"][1].as_str().unwrap().into())));let mut payload=String::with_capacity(4096);payload.push_str(law["payload"].as_str().unwrap());let edit=authority.next_edit(payload.clone(),vec![payload.clone()]);let prepared=authority.prepare_one_item(edit,Arc::new(payload)).unwrap();let mutations:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(OwnedValueRetirementFactory::<String>::default());let snapshots:Arc<dyn SnapshotRetirementFactory<String>>=Arc::new(SharedValueRetirementFactory::<String>::default());(prepared,mutations,snapshots)});let held=heap.requested_bytes-heap.released_bytes;let edit_pointer=prepared.edit()as*const Edit<String>;let post_pointer=Arc::as_ptr(&prepared.post_snapshot());let mutation_pointer=Arc::as_ptr(&mutations);let snapshot_pointer=Arc::as_ptr(&snapshots);let birth=ArtifactStoreOneItemPrepared::<String,String>::retirement_birth_demand();let grant=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:birth.capacity_bytes-1,maximum_depth:birth.depth,..Default::default()};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||prepared.admit_retirement(mutations,snapshots,grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(_,prepared,mutations,snapshots)=match result{Err(original)=>original,Ok(_)=>panic!("unfunded original prepared admission succeeded")};assert_eq!(prepared.edit()as*const Edit<String>,edit_pointer);assert_eq!(Arc::as_ptr(&prepared.post_snapshot()),post_pointer);assert!(std::ptr::addr_eq(Arc::as_ptr(&mutations),mutation_pointer));assert!(std::ptr::addr_eq(Arc::as_ptr(&snapshots),snapshot_pointer));let grant=RetainedCloneGrant{maximum_capacity_bytes:birth.capacity_bytes,..grant};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||prepared.admit_retirement(mutations,snapshots,grant));let(owner,receipt)=result.unwrap_or_else(|_|panic!("actual prepared frame refused exact admission"));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,0));let(mut born,mut released)=(heap.requested_bytes,0);let mut owner=Some(owner);
 let mut still=0usize;let mut ticket=FactoryTicketClose::default();
 for turn in 0..1000000{if owner.is_none(){break}let demand=ticket.next_demand(&owner,body).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes.max(body),maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};for under in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:0,..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant})].into_iter().flatten(){let result=close(&mut owner,&mut ticket,body,under);if let Ok(step)=result.result{assert_eq!(step.progress(),Default::default());}}let step=close(&mut owner,&mut ticket,body,grant).result.unwrap();assert!(step.progress().fits(grant));if step.progress()==Default::default(){still+=1;assert!(still<STALL_TURNS,"prepared retirement made no progress for {STALL_TURNS} turns at {demand:?} (body {body}, turn {turn})");}else{still=0}born+=step.progress().retained_capacity_bytes;released+=step.progress().released_bytes;}
 assert!(owner.is_none());assert_eq!(released,held+born);
 }
}